function applyReviewedRouteTitle(f){const a=f.attributes,entry=reviewedRouteTitles[String(a.Ruta)];if(entry&&entry.line===String(a.LabelLinea||a.Linea)&&entry.sourcePackage===a.Package)a.NombreRuta=entry.title;}
function validFeatures(data){
 if(data.error||!Array.isArray(data.features)||!data.features.length||data.exceededTransferLimit)throw Error('La fuente ha devuelto datos incompletos.');
 for(const f of data.features){if(!f.geometry?.paths?.length)throw Error('Falta el trazado de un recorrido.');for(const p of f.geometry.paths){if(p.length<2||p.some(c=>!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>90))throw Error('Coordenadas no válidas.');}}
 for(const f of data.features){for(const k of ['NombreLinea','NombreRuta','DestinoRuta'])if(typeof f.attributes[k]==='string')f.attributes[k]=cleanLineTitle(f.attributes[k]);f.attributes.NombreLinea=lineTitleCorrections[String(f.attributes.LabelLinea||f.attributes.Linea)]||f.attributes.NombreLinea;if(String(f.attributes.LabelLinea||f.attributes.Linea)==='39'){const destination=String(f.attributes.DestinoRuta||'').replace(/[^a-záéíóúñ]/gi,'').toUpperCase();f.attributes.NombreRuta=destination==='LOSARCOS'?'Hacienda San Antonio - Los Arcos':'Los Arcos - Hacienda San Antonio';}applyReviewedRouteTitle(f);for(const s of f.stops||[])s.attributes.Nombre=publicName(s.attributes.Nombre);}
 return data.features;
}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const label=f=>String(f.attributes.LabelLinea||f.attributes.Linea);
const title=f=>`${label(f)} - ${f.attributes.NombreRuta||f.attributes.NombreLinea||('Hacia '+f.attributes.DestinoRuta)}`;
const safeFilename=name=>String(name).normalize('NFC').replace(/[<>:"/\\|?*\x00-\x1f]/g,'-').replace(/\s+/g,' ').trim().replace(/[. ]+$/g,'');
function routeFilename(f,all=[]){const base=safeFilename(title(f));const duplicates=all.filter(other=>safeFilename(title(other)).toLocaleLowerCase('es')===base.toLocaleLowerCase('es'));return base+(duplicates.length>1?' - variante '+f.attributes.Ruta+'-'+f.attributes.ObjectId:'');}
function waypoints(features){return features.flatMap(f=>(f.stops||[]).map((s,i)=>'<wpt lat="'+s.geometry.y+'" lon="'+s.geometry.x+'"><name>'+esc(String(i+1).padStart(2,'0')+' · '+s.attributes.Nombre)+'</name><cmt>'+esc('Parada '+s.attributes.Nodo+' · Línea '+label(f)+' · Ruta '+f.attributes.Ruta)+'</cmt><desc>'+esc(title(f))+'</desc><sym>Bus Stop</sym><type>Parada de autobús</type></wpt>')).join('');}
function gpx(features){const testOnly=features.every(f=>f.attributes.TestRoute==='alcala-torreblanca-v1');return '<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="Copiloter" xmlns="http://www.topografix.com/GPX/1/1"><metadata><name>'+esc(features.length===1?title(features[0]):testOnly?'Líneas ficticias de prueba':'Líneas de autobús de Sevilla')+'</name><desc>'+esc(testOnly?'Línea ficticia de prueba. Trazado de conducción: OSRM / OpenStreetMap. Las cabeceras no son paradas de autobús reales.':'Fuente: IDE Sevilla. Trazados publicados, sin tiempos, altitudes ni desvíos en tiempo real.')+'</desc><link href="'+(testOnly?'https://www.openstreetmap.org/copyright':SOURCE)+'"><text>Fuente de los recorridos</text></link></metadata>'+waypoints(features)+features.map(f=>'<trk><name>'+esc(title(f))+'</name>'+f.geometry.paths.map(p=>'<trkseg>'+p.map(c=>'<trkpt lat="'+c[1]+'" lon="'+c[0]+'"/>').join('')+'</trkseg>').join('')+'</trk>').join('')+'</gpx>';}
function distance(f){let km=0;for(const p of f.geometry.paths)for(let i=1;i<p.length;i++){const a=p[i-1],b=p[i],rad=Math.PI/180;const h=Math.sin((b[1]-a[1])*rad/2)**2+Math.cos(a[1]*rad)*Math.cos(b[1]*rad)*Math.sin((b[0]-a[0])*rad/2)**2;km+=12742*Math.asin(Math.sqrt(Math.min(1,h)));}return km;}

